<script setup>
import { computed, ref } from 'vue'
const range=ref(6), filters=ref(false), visible=ref(['Sleep','Symptoms','Period'])
const cycles=[
 {name:'P1',date:'27 Apr',days:28,sleep:7.4,symptoms:['Cramps','Fatigue','Bloating','Back pain','Cravings','Headache'],bleed:'Medium',period:4},
 {name:'P2',date:'25 May',days:29,sleep:6.8,symptoms:['Cramps','Fatigue','Headache','Bloating','Mood swings','Back pain','Nausea','Low appetite'],bleed:'Heavy',period:5},
 {name:'P3',date:'23 Jun',days:30,sleep:7.6,symptoms:['Cramps','Fatigue','Bloating','Cravings'],bleed:'Light',period:3},
 {name:'P4',date:'23 Jul',days:31,sleep:6.2,symptoms:['Cramps','Fatigue','Migraine','Bloating','Back pain','Nausea','Dizziness','Anxiety'],bleed:'Heavy',period:7},
 {name:'P5',date:'23 Aug',days:29,sleep:7.0,symptoms:['Cramps','Fatigue','Bloating','Migraine','Cravings','Anxiety'],bleed:'Medium',period:4},
 {name:'P6',date:'21 Sep',days:27,sleep:7.2,symptoms:['Cramps','Fatigue','Bloating','Migraine','Mood swings'],bleed:'Medium',period:4}
]
const selected=computed(()=>range.value===3?cycles.slice(-3):cycles)
const avg=(key)=> (selected.value.reduce((a,c)=>a+(key==='symptoms'?c.symptoms.length:c[key]),0)/selected.value.length).toFixed(1)
const series=computed(()=>[{name:'Sleep',color:'#3552c9',bg:'#eef1fd',unit:'h avg',value:avg('sleep'),data:selected.value.map(c=>c.sleep)},{name:'Symptoms',color:'#c2610c',bg:'#fdf0e3',unit:'avg',value:avg('symptoms'),data:selected.value.map(c=>c.symptoms.length)},{name:'Period',color:'#b2284f',bg:'#fbe9ef',unit:'d avg',value:avg('period'),data:selected.value.map(c=>c.period)}])
const x=i=>38+i*(296/(selected.value.length-1)), y=n=>180-n*17
const points=data=>data.map((n,i)=>`${x(i)},${y(n)}`).join(' ')
function toggle(name){visible.value=visible.value.includes(name)?visible.value.filter(n=>n!==name):[...visible.value,name]}
</script>
<template>
<div class="design-screen stack">
 <header class="page-header"><div><h1>Patterns</h1><p class="muted">{{range===3?'Last 3 cycles · Jul – Oct 2026':range===6?'Last 6 cycles · Apr – Oct 2026':'All recorded cycles · Apr – Oct 2026'}}</p></div><button class="icon-btn" aria-label="Filter patterns" :aria-expanded="filters" @click="filters=!filters"><svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 5h14M6 10h8M8.5 15h3"/></svg></button></header>
 <div class="range-switch"><button v-for="r in [3,6,0]" :key="r" :aria-pressed="range===r" @click="range=r">{{r?r+' cycles':'All time'}}</button></div>
 <section v-if="filters" class="card"><h2>Show trends</h2><div class="chip-row"><button v-for="s in series" :key="s.name" class="chip" :aria-pressed="visible.includes(s.name)" @click="toggle(s.name)">{{s.name}}</button></div></section>
 <section class="card"><div class="section-link"><h2>Trends</h2><a href="#symptoms">Explore symptoms ↗</a></div>
 <div class="trend-metrics"><div v-for="s in series" :key="s.name" :style="{background:s.bg,color:s.color}"><span><i :style="{background:s.color}"/>{{s.name}}</span><strong>{{s.value}}<small>{{s.unit}}</small></strong></div></div>
 <svg viewBox="0 0 358 222" width="100%" role="img" :aria-label="`Trends over ${selected.length} recorded cycles: sleep in hours, symptoms logged, and period length in days.`"><g v-for="n in [0,2,4,6,8,10]" :key="n"><line x1="34" :y1="y(n)" x2="340" :y2="y(n)" stroke="#e6e8f3"/><text x="26" :y="y(n)+4" text-anchor="end" fill="#5a5f85" font-size="10">{{n}}</text></g><g v-for="s in series.filter(s=>visible.includes(s.name))" :key="s.name"><polyline :points="points(s.data)" fill="none" :stroke="s.color" stroke-width="2.5" :stroke-dasharray="s.name==='Sleep'?'':s.name==='Symptoms'?'6 4':'1 5'"/><circle v-for="(n,i) in s.data" :key="i" :cx="x(i)" :cy="y(n)" r="3.5" :fill="s.name==='Sleep'?'white':s.color" :stroke="s.color" stroke-width="2"/></g><g v-for="(c,i) in selected" :key="c.name" text-anchor="middle"><text :x="x(i)" y="199" font-size="11" font-weight="700" fill="#1d2140">{{c.name}}</text><text :x="x(i)" y="215" font-size="10" fill="#5a5f85">{{c.date}}</text></g></svg>
 <p class="chart-note">One shared 0–10 scale: sleep in hours, symptoms as number logged, period in days.</p></section>
 <section class="cycles-section"><div class="section-link"><h2>Cycle patterns</h2><span class="muted">Avg cycle {{Math.round(Number(avg('days')))}} days</span></div><div class="cycle-table"><div class="cycle-row table-head"><span>Pattern</span><span>Cycle</span><span>Symptoms</span><span>Sleep</span><span>Bleed</span></div><div v-for="c in selected" :key="c.name" class="cycle-row"><div><strong>{{c.name}}</strong><small>{{c.date}}</small></div><div><strong>{{c.days}}</strong><small>days</small></div><div class="symptom-pills"><span v-for="s in c.symptoms" :key="s" class="pill">{{s}}</span></div><div class="sleep-cell"><strong>{{c.sleep.toFixed(1)}}</strong><small>hrs</small></div><div class="bleed-cell"><div aria-hidden="true"><span v-for="n in 3" :key="n" :class="{faded:n>(c.bleed==='Heavy'?3:c.bleed==='Medium'?2:1)}">♦</span></div><small>{{c.bleed}}</small></div></div></div></section>
 <section class="card insight"><div class="eyebrow">A little insight</div><h2>Your cycle tells a story</h2><p>Your symptoms tend to peak in the week before your period. Lower sleep and increased symptoms overlap in your heaviest cycles.</p><a href="#overlaps" class="secondary full">View key patterns and overlaps →</a></section>
 <section class="card summary-cta"><span class="eyebrow">Make your next conversation easier</span><h2>Your experience, in your own words.</h2><p class="muted">Bring your patterns, symptoms and what you have tried together for your healthcare professional.</p><a href="#questions" class="primary full">Create my GP summary →</a><span class="muted">Nothing is shared until you choose to send it.</span></section>
 <p class="muted demo-note">Sample cycle data · For demonstration</p>
</div>
</template>
<style scoped>
.range-switch{display:flex;gap:4px;padding:4px;margin:2px 16px 0;background:#e6e8f5;border-radius:14px}.range-switch button{flex:1;height:44px;border:0;background:transparent;border-radius:10px;color:#4a4f78;font-size:13px}.range-switch button[aria-pressed=true]{background:#fff;box-shadow:0 1px 3px #1d214020;color:#1d2140;font-weight:700}.trend-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:0 0 15px}.trend-metrics>div{padding:10px;border-radius:12px}.trend-metrics span{display:flex;align-items:center;gap:5px;font-size:11px;font-weight:600}.trend-metrics i{width:12px;height:3px;border-radius:3px}.trend-metrics strong{display:block;color:#1d2140;font-size:18px;margin-top:5px}.trend-metrics small{font-size:10px;color:#5a5f85;font-weight:400;margin-left:4px}.chart-note{font-size:10px;line-height:1.6;color:#5a5f85;margin:6px 0 0}.cycles-section{margin:3px 12px 0}.cycles-section>.section-link{padding:0 4px}.cycles-section h2{margin-bottom:10px}.cycles-section .muted{font-size:10px}.cycle-table{background:white;border-radius:18px;overflow:hidden;box-shadow:0 1px 3px #1d214012}.cycle-row{display:grid;grid-template-columns:43px 33px minmax(0,1fr) 34px 46px;gap:7px;align-items:center;padding:13px 10px;border-top:1px solid #e6e8f3}.table-head{background:#f8f9fd;border:0;font-size:10px;color:#4a4f78;font-weight:700;padding-top:12px;padding-bottom:10px}.cycle-row strong{font-size:14px}.cycle-row small{display:block;font-size:10px;color:#5a5f85;line-height:1.5}.symptom-pills{display:flex;flex-wrap:wrap;gap:4px}.pill{padding:4px 6px;font-size:9px}.sleep-cell strong{color:#2b44a8}.bleed-cell{color:#b2284f}.bleed-cell small{color:inherit;font-size:9px}.bleed-cell .faded{color:#e9d5dd}.insight{background:#eee4f4}.insight h2{margin:7px 0}.insight p{font-size:12px;line-height:1.8;color:#64516f}.insight a,.summary-cta a{display:block;text-align:center}.summary-cta h2{margin-top:10px;font-size:19px}.summary-cta>span:last-child{display:block;text-align:center;font-size:10px;margin-top:10px}.demo-note{text-align:center;font-size:10px}
</style>
